        "평가사유": "[화제성 8점] (확정 사실 →) 넷플릭스가 제작을 공식 발표했고 노희경 극본 × 이윤정 연출에 송혜교·공유·차승원·이하늬가 붙은 캐스팅이다. 배우.json에서 공유는 톱급, 제작사.json에서 넷플릭스 코리아는 톱급이다. 제작비 750억 규모라는 보도도 나왔다. (추정 →) 다만 실무자 캘리브레이션이 OTT 대작의 화제성을 박하게 본 전례(동궁 8→6)가 있어 9~10점은 주지 않는다.\n[독창성 6점] (확정 사실 →) 1960~80년대 연예계라는 시대·업계 설정은 국내 드라마에서 드물어 소재 희소성이 있다. 다만 '가진 것 없는 이들의 성공 분투기'라는 뼈대 자체는 노희경 전작들과 겹치고 시대극 성장 서사의 전형을 따른다.\n[근접성 9점] (확정 사실 →) 한국 제작·한국 근현대 정서 직결이며, 실무자 보정원칙 2에 따라 넷플릭스 플랫폼 접근성을 근접성 가점으로 인정한다.\n[영향성 7점] (추정 →) 대형 예산과 톱 캐스팅으로 공개 주 화제를 독점할 가능성이 크지만, 시대극 정서가 글로벌·젊은층 확산을 제한할 수 있어 9점까지는 보지 않는다.\n[종합] 강점: 노희경·송혜교·공유라는 검증된 조합 + 12월 공개 타이밍. 약점: 22부작 장편이라 중도 이탈 위험이 크고, 넷플릭스가 12/11 공개를 확정(10-22 회차)했으나 같은 주 듄·어벤져스 극장 텐트폴과 화제 분산 가능성이 있다. 편성 관점: 12월 둘째 주 OTT 최대어로 확정.",
