        "평가사유": "[화제성 7점] 확정 사실 → 전도연(배우 DB 톱급, 칸 여우주연상)·박해수(오징어게임) 주연에 김선영·백현진 등 연기파 조연 라인업이 언론(위키트리·TV리포트·일간스포츠)에 '초호화 캐스팅'으로 보도됨. 추정 → 집값·재개발이라는 전 국민 관심 소재라 첫 방송 전후 언급량은 높겠으나, 공개 전 화제 지표(검색량 등)는 아직 없어 8점 이상은 보류.\n[독창성 7점] 확정 사실 → 네이버 웹툰 원작, 부녀회 대 재개발 조합이라는 '아줌마 느와르' 설정. 아파트·부동산 욕망을 블랙코미디·스릴러로 다루는 드라마는 드물어 소재 희소성이 뚜렷함. 다만 웹툰 원작 각색 자체는 흔한 경로이고, 비슷한 부동산 풍자물(대한민국에서 건물주 되는 법 등)이 최근 tvN에 있었음.\n[근접성 9점] 확정 사실 → 한국 제작, tvN 방송·티빙 동시 공개로 국내 접근성 최상. 한강뷰 아파트 집값이라는 소재가 한국 시청자 생활감과 직결됨.\n[영향성 7점] 추정 → 집값·재개발 갈등은 시사 이슈와 맞물려 기사화·커뮤니티 확산 여지가 큼. 단 tvN 토일극 시청률은 편차가 커 흥행이 확정된 것은 아니고, 12부작 단기물이라 파급 기간이 짧을 수 있음.\n[종합] 강점: 톱급 배우 + 생활 밀착형 사회 소재. 약점: 첫 방송일(1/16)은 위키 단독 기재로 언론은 '2027년 상반기'로만 보도해 윈도우 내 공개가 불확실, 블랙코미디 톤은 호불호 가능. 편성 관점: 1월 편성 확정 보도가 나오면 윈도우 내 국내 드라마 최상위 후보.",
