        "평가사유": "[화제성 5점] (확정 →) MMCA 2026년 전시계획과 KCISA API에 2026-11-20~2027-04-04, 국립현대미술관 서울로 등재. 그래픽디자인과 시각문화의 관계를 '종이에서 픽셀로'의 이행으로 풀어내는 대형 기획전이다. (추정 →) 참여 작가·출품 규모 미공개. 디자인 기획전은 일반 대중 인지도가 미술 거장전보다 낮다.\n[독창성 5점] (독점성·희소성·차별 기획 관점) 국립미술관이 그래픽디자인을 정면으로 다루는 대형 기획전은 드물어 주제 희소성이 있다. 다만 공개 전시로 독점권이 없어 상단은 제한했다.\n[근접성 8점] (수도권/지방·기간·관객 친숙도) 서울 종로 MMCA 서울, 11-20~2027-04-04 약 4개월 반 장기. 접근성 최상위.\n[영향성 7점] 디자인·출판·플랫폼 영역과의 연계 소재가 풍부하고, 미술·디자인 기획전은 매체 정체성과 정합해 신뢰도 제고에 기여한다(캘리브레이션 원칙 4).\n[종합] 강점: 서울 장기, 연계 콘텐츠 확장성 높음, 주제 희소. 약점·리스크: 대중 인지도가 낮아 단독 기사로는 반응이 제한될 수 있고 참여 작가 라인업이 미공개다. 편성 관점: 같은 시기 MMCA 과천 《조지아 오키프》와 묶어 'MMCA 겨울 2대 기획전'으로 다루면 화제성 열위를 보완할 수 있다.",
